// src/pages/Dashboard.jsx
import React from "react";
import { useTheme } from "../context/ThemeContext";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
} from "recharts";

const Dashboard = () => {
  const { theme } = useTheme();

  const colors = {
    pageBg: theme === "dark" ? "#020c1b" : "#f5f7fb",
    cardBg: theme === "dark" ? "#071426" : "#ffffff",
    text: theme === "dark" ? "#e6edf3" : "#0f172a",
    line: theme === "dark" ? "#38bdf8" : "#2563eb",
  };

  const cardStyle = {
    backgroundColor: colors.cardBg,
    borderRadius: "14px",
    padding: "24px",
    color: colors.text,
    boxShadow: "0 6px 22px rgba(0,0,0,0.15)",
    flex: 1,
  };

  // 📊 тестовые данные (потом заменишь на API)
  const chartData = [
    { day: "Mon", checks: 5 },
    { day: "Tue", checks: 9 },
    { day: "Wed", checks: 7 },
    { day: "Thu", checks: 11 },
    { day: "Fri", checks: 6 },
    { day: "Sat", checks: 4 },
    { day: "Sun", checks: 8 },
  ];

  return (
    <div
      style={{
        backgroundColor: colors.pageBg,
        minHeight: "100vh",
        padding: "40px 60px",
        color: colors.text,
      }}
    >
      <h1 style={{ fontSize: "32px", textAlign: "center", marginBottom: "40px" }}>
        Dashboard
      </h1>

      {/* Top Stats */}
      <div style={{ display: "flex", gap: "20px", marginBottom: "30px" }}>
        <div style={cardStyle}>
          <h3>Total Checks</h3>
          <p style={{ fontSize: "26px", marginTop: "10px" }}>128</p>
        </div>

        <div style={cardStyle}>
          <h3>Average Plagiarism</h3>
          <p style={{ fontSize: "26px", marginTop: "10px" }}>15%</p>
        </div>

        <div style={cardStyle}>
          <h3>Last Report Score</h3>
          <p style={{ fontSize: "26px", marginTop: "10px" }}>85%</p>
        </div>
      </div>

      {/* Graph Section */}
      <div
        style={{
          ...cardStyle,
          height: "320px",
          display: "flex",
          flexDirection: "column",
        }}
      >
        <h3>Checks in the Last 7 Days</h3>

        <div style={{ flex: 1, marginTop: "20px" }}>
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData}>
              <XAxis dataKey="day" stroke={colors.text} />
              <YAxis stroke={colors.text} />
              <Tooltip />
              <Line
                type="monotone"
                dataKey="checks"
                stroke={colors.line}
                strokeWidth={3}
                dot={{ r: 4 }}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Recent Checks */}
      <div style={{ marginTop: "40px", ...cardStyle }}>
        <h3 style={{ marginBottom: "20px" }}>Recent Checks</h3>

        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ borderBottom: `1px solid ${colors.text}40` }}>
              <th align="left">Date</th>
              <th align="left">Score</th>
              <th align="left">File</th>
              <th align="left">Status</th>
            </tr>
          </thead>
          <tbody>
            {[
              ["Apr 25, 2024", "84%", "Thesis_Draft.pdf", "Completed"],
              ["Apr 24, 2024", "17%", "Chapter2.docx", "Completed"],
              ["Apr 22, 2024", "23%", "review.pdf", "Completed"],
            ].map((row, i) => (
              <tr key={i} style={{ borderBottom: `1px solid ${colors.text}20` }}>
                {row.map((cell, j) => (
                  <td key={j} style={{ padding: "10px 0", opacity: 0.9 }}>
                    {cell}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Dashboard;
